-- Translations of the demo projects (generated from supabase/translations/*.json).
update public.projects set translations = $json${"ar":{"title":"إقامة الياسمين","tagline":"تمويل استكمال 24 شقة بالنصر","description":"اكتملت الأشغال الكبرى و60% من الوحدات محجوزة مسبقًا. تُكمِل الأموال المجمّعة الأموال الذاتية التي يشترطها البنك لتمويل أشغال التشطيب. ويستردّ المستثمرون أموالهم عند بيع الشقق.","highlights":["اكتمال الأشغال الكبرى","60% من الوحدات محجوزة","ضمان برهن عقاري من الدرجة الأولى (مبرمج)"],"risks":["تأخر الأشغال أو المبيعات","تعثّر الباعث العقاري","رأس المال غير مضمون، ولا إمكانية لإعادة البيع قبل حلول الأجل"],"city":"النصر"},"en":{"title":"Yasmine Residence","tagline":"Funding the completion of 24 apartments in Ennasr","description":"The structural work is complete and 60% of the units are already reserved. The funds top up the equity the bank requires to finance the finishing works. Investors are repaid as the apartments are sold.","highlights":["Structural work complete","60% of units reserved","First-ranking mortgage guarantee (planned)"],"risks":["Construction or sales delays","Developer default","Capital not guaranteed; no resale before maturity"]},"de":{"title":"Résidence Yasmine","tagline":"Die Fertigstellung von 24 Wohnungen in Ennasr finanzieren","description":"Der Rohbau ist abgeschlossen und 60 % der Wohneinheiten sind bereits reserviert. Die Mittel ergänzen das Eigenkapital, das die Bank für die Finanzierung des Innenausbaus verlangt. Die Rückzahlung an die Anleger erfolgt beim Verkauf der Wohnungen.","highlights":["Rohbau abgeschlossen","60 % der Wohneinheiten reserviert","Erstrangige Hypothek als Sicherheit (geplant)"],"risks":["Verzögerungen beim Bau oder beim Verkauf","Ausfall des Bauträgers","Kapital nicht garantiert, kein Weiterverkauf vor Laufzeitende"]},"it":{"title":"Résidence Yasmine","tagline":"Finanziare il completamento di 24 appartamenti a Ennasr","description":"Le opere strutturali sono terminate e il 60% delle unità è già prenotato. I fondi integrano il capitale proprio richiesto dalla banca per finanziare le finiture. Gli investitori vengono rimborsati alla vendita degli appartamenti.","highlights":["Opere strutturali terminate","60% delle unità prenotate","Ipoteca di primo grado (prevista)"],"risks":["Ritardi nel cantiere o nelle vendite","Insolvenza del promotore","Capitale non garantito, nessuna rivendita prima della scadenza"]}}$json$::jsonb where slug = 'residence-yasmine-ennasr';
update public.projects set translations = $json${"ar":{"title":"دار الجالية — سهلول","tagline":"6 شقق مفروشة للكراء قرب جامعات سوسة","description":"تشتري شركة المشروع ست شقق وتعرضها للكراء لفائدة الطلبة والشباب العاملين. تُوزَّع معينات الكراء الصافية كل سنة، وتُباع الشقق من جديد عند حلول الأجل.","highlights":["طلب قوي على الكراء من قبل الطلبة","التصرّف في الكراء موكول إلى طرف مختص","متاح للتونسيين المقيمين بالخارج"],"risks":["فترات شغور دون كراء","انخفاض الأسعار عند إعادة البيع","مخاطر الصرف بالنسبة إلى المستثمرين غير المقيمين"],"city":"سوسة"},"en":{"title":"Dar Diaspora — Sahloul","tagline":"6 furnished apartments to let near the universities of Sousse","description":"A project company buys six apartments and lets them to students and young professionals. Net rental income is distributed every year; the apartments are sold at maturity.","highlights":["Strong student rental demand","Professional letting management","Open to Tunisians living abroad"],"risks":["Rental vacancy","Fall in resale prices","Currency risk for non-resident investors"]},"de":{"title":"Dar Diaspora — Sahloul","tagline":"6 möblierte Mietwohnungen nahe den Universitäten von Sousse","description":"Eine Projektgesellschaft kauft sechs Wohnungen und vermietet sie an Studierende und junge Berufstätige. Die Nettomieteinnahmen werden jährlich ausgeschüttet; am Laufzeitende werden die Wohnungen wieder verkauft.","highlights":["Hohe Mietnachfrage von Studierenden","Ausgelagerte Mietverwaltung","Auch für im Ausland lebende Tunesier zugänglich"],"risks":["Leerstand","Sinkende Preise beim Wiederverkauf","Wechselkursrisiko für nicht in Tunesien ansässige Anleger"]},"it":{"title":"Dar Diaspora — Sahloul","tagline":"6 appartamenti arredati in affitto vicino alle università di Sousse","description":"Una società di progetto acquista sei appartamenti e li affitta a studenti e giovani lavoratori. I canoni netti vengono distribuiti ogni anno; alla scadenza gli appartamenti vengono rivenduti.","highlights":["Forte domanda di affitti da parte degli studenti","Gestione degli affitti affidata a terzi","Accessibile ai tunisini residenti all'estero"],"risks":["Periodi di sfitto","Calo dei prezzi alla rivendita","Rischio di cambio per gli investitori non residenti"]}}$json$::jsonb where slug = 'dar-diaspora-sahloul';
update public.projects set translations = $json${"ar":{"title":"سكن خطوة بخطوة — صفاقس الجديدة","tagline":"ثلاث عائلات تتملّك مساكنها تدريجيًا","description":"تشتري الشركة ثلاث شقق. تدفع كل عائلة معين كراء وتشتري حصصًا من مسكنها كل شهر إلى أن تصبح مالكة له بالكامل. هيكلة في شكل صكوك، متوافقة مع أحكام المالية الإسلامية.","highlights":["النفاذ إلى الملكية دون قرض بنكي","مداخيل منتظمة","هيكلة في شكل صكوك"],"risks":["تخلّف عائلة عن الدفع","الإطار القانوني للكراء المملّك يتطلب التثبّت","مدة طويلة (10 سنوات)"],"city":"صفاقس"},"en":{"title":"Sakan Step — Sfax El Jadida","tagline":"Three families become homeowners step by step","description":"The company buys three apartments. Each family pays rent and buys shares in its home every month until it owns it outright. Sukuk structure, compliant with Islamic finance.","highlights":["Home ownership without a bank loan","Regular income","Sukuk structure"],"risks":["Payment default by a family","Legal framework for rent-to-own still to be confirmed","Long term (10 years)"]},"de":{"title":"Sakan Step — Sfax El Jadida","tagline":"Drei Familien werden Schritt für Schritt Eigentümer","description":"Die Gesellschaft kauft drei Wohnungen. Jede Familie zahlt Miete und erwirbt jeden Monat Anteile, bis sie vollständig Eigentümerin ihrer Wohnung ist. Sukuk-Struktur, im Einklang mit den Grundsätzen des islamischen Finanzwesens.","highlights":["Wohneigentum ohne Bankkredit","Regelmäßige Erträge","Sukuk-Struktur"],"risks":["Zahlungsausfall einer Familie","Rechtsrahmen für den Mietkauf muss noch bestätigt werden","Lange Laufzeit (10 Jahre)"]},"it":{"title":"Sakan Step — Sfax El Jadida","tagline":"Tre famiglie diventano proprietarie passo dopo passo","description":"La società acquista tre appartamenti. Ogni famiglia paga un canone e riscatta delle quote ogni mese, fino a diventarne pienamente proprietaria. Struttura in sukuk, conforme alla finanza islamica.","highlights":["Accesso alla proprietà senza mutuo bancario","Entrate regolari","Struttura sukuk"],"risks":["Mancato pagamento da parte di una famiglia","Quadro giuridico dell'affitto con riscatto da verificare","Durata lunga (10 anni)"]}}$json$::jsonb where slug = 'sakan-step-sfax';
update public.projects set translations = $json${"ar":{"title":"دار لبنة — مدينة تونس العتيقة","tagline":"ترميم دار تقليدية وتحويلها إلى دار ضيافة","description":"ترميم دار تعود إلى القرن التاسع عشر وتحويلها إلى دار ضيافة من 8 غرف، يتولى استغلالها مسيّر مختص. ويحصل المستثمرون على حصة من نتيجة الاستغلال.","highlights":["تراث معماري","سياحة ثقافية في نموّ","مستغِلّ ذو خبرة"],"risks":["موسمية النشاط السياحي","تجاوز ميزانية الترميم","التراخيص المتعلقة بحماية التراث"],"city":"تونس"},"en":{"title":"Dar Lebna — Medina of Tunis","tagline":"Restoring a traditional house as a guest house","description":"Restoration of a 19th-century dar (traditional courtyard house) into an 8-room guest house, run by a specialist operator. Investors receive a share of the operating profit.","highlights":["Architectural heritage","Growing cultural tourism","Experienced operator"],"risks":["Seasonal tourism","Restoration budget overrun","Heritage permits"]},"de":{"title":"Dar Lebna — Medina von Tunis","tagline":"Ein traditionelles Haus restaurieren und als Gästehaus betreiben","description":"Restaurierung eines traditionellen Hauses (Dar) aus dem 19. Jahrhundert zu einem Gästehaus mit 8 Zimmern, geführt von einem spezialisierten Betreiber. Die Anleger erhalten einen Anteil am Betriebsergebnis.","highlights":["Architektonisches Kulturerbe","Wachsender Kulturtourismus","Erfahrener Betreiber"],"risks":["Saisonabhängigkeit des Tourismus","Überschreitung des Restaurierungsbudgets","Denkmalschutzrechtliche Genehmigungen"]},"it":{"title":"Dar Lebna — Medina di Tunisi","tagline":"Restaurare una casa tradizionale e trasformarla in guest house","description":"Restauro di una dar del XIX secolo, trasformata in una guest house di 8 camere e gestita da un operatore specializzato. Gli investitori ricevono una quota del risultato di gestione.","highlights":["Patrimonio architettonico","Turismo culturale in crescita","Gestore esperto"],"risks":["Stagionalità del turismo","Superamento del budget di restauro","Autorizzazioni per la tutela del patrimonio"],"city":"Tunisi"}}$json$::jsonb where slug = 'dar-medina-tunis';
